// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.workerimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport com.roshan.persona.automation.scheduler.AutomationSchedulerimport dagger.hilt.EntryPointimport dagger.hilt.InstallInimport dagger.hilt.android.EntryPointAccessorsimport dagger.hilt.components.SingletonComponentimport timber.log.Timber/** * NOUS — Automation Boot Receiver (Module 8). * * REAL [BroadcastReceiver] that listens for `BOOT_COMPLETED` and reschedules * all automation rules after a device reboot. * * ## Why this is needed * * WorkManager automatically re-applies its persisted work requests after a * reboot — but only if those requests were enqueued before the reboot. * However, two cases require explicit re-scheduling: * *   1. **Geofences** — GeofencingClient geofences DO survive reboot (Play *      Services re-registers them internally), but only if the PendingIntent *      is still valid. We re-register to be safe. *   2. **Dynamic BroadcastReceivers** — These are registered via *      `Context.registerReceiver` and DO NOT survive reboot (the registration *      is per-process). We need to re-register them. * * ## How the receiver gets registered * * Declared in `AndroidManifest.xml` with an `<intent-filter>` for * `BOOT_COMPLETED`. The `RECEIVE_BOOT_COMPLETED` permission is also declared * in the manifest. * * ## What the receiver does * *   1. Get the singleton [AutomationScheduler] via Hilt EntryPointAccessors. *   2. Iterate all rules from [com.roshan.persona.automation.engine.AutomationEngine]. *   3. For each enabled rule, call `scheduler.schedule(rule)` — this re-registers *      geofences + receivers + WorkManager work. * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2 Automation</a> */class AutomationBootReceiver : BroadcastReceiver() {    companion object {        private const val TAG = "AutomationBootReceiver"    }    override fun onReceive(context: Context, intent: Intent) {        val action = intent.action ?: return        if (action != Intent.ACTION_BOOT_COMPLETED &&            action != Intent.ACTION_LOCKED_BOOT_COMPLETED &&            action != "android.intent.action.QUICKBOOT_POWERON" &&            action != "com.htc.intent.action.QUICKBOOT_POWERON"        ) {            return        }        Timber.tag(TAG).i("Boot completed — rescheduling all automation rules.")        val entryPoint = EntryPointAccessors.fromApplication(            context.applicationContext,            BootReceiverEntryPoint::class.java,        )        val engine = entryPoint.automationEngine()        val scheduler = entryPoint.scheduler()        // Reschedule all enabled rules.        val rules = engine.listRules()        var scheduled = 0        for (rule in rules) {            if (rule.isEnabled) {                scheduler.schedule(rule)                scheduled++            }        }        Timber.tag(TAG).i("Rescheduled %d/%d automation rules after boot.", scheduled, rules.size)    }}/** * Hilt entry point for accessing [com.roshan.persona.automation.engine.AutomationEngine] * + [AutomationScheduler] from the boot receiver. */@EntryPoint@InstallIn(SingletonComponent::class)interface BootReceiverEntryPoint {    /** Access the singleton [com.roshan.persona.automation.engine.AutomationEngine]. */    fun automationEngine(): com.roshan.persona.automation.engine.AutomationEngine    /** Access the singleton [AutomationScheduler]. */    fun scheduler(): AutomationScheduler}